UPDATE CONTENT_POPUP
   SET EXPOSE_YN = #{exposeYn},
       MDFCN_DT  = UTC_TIMESTAMP(6),
       MDFR_SN   = #{mdfrSn}
 WHERE CONTENT_POPUP_SN = #{contentPopupSn}
   AND DEL_YN = 'N'

UPDATE CONTENT_POPUP
   SET DEL_YN   = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE CONTENT_POPUP_SN = #{contentPopupSn}
   AND DEL_YN = 'N'
